using System;using System.IO;using System.Linq;using System.Drawing;using System.Reflection;using System.Collections.Generic;using System.Windows.Forms;using Musikbox;using MusikboxTests;
class Studio60Tests {
 static int count;static void Check(bool value,string message){if(!value)throw new Exception(message);count++;Console.WriteLine("PASS "+message);}static object Field(object value,string name){return value.GetType().GetField(name,BindingFlags.NonPublic|BindingFlags.Instance).GetValue(value);}static object Call(object value,string name,params object[] args){var type=value.GetType();while(type!=null){var method=type.GetMethod(name,BindingFlags.NonPublic|BindingFlags.Instance|BindingFlags.DeclaredOnly);if(method!=null)return method.Invoke(value,args);type=type.BaseType;}throw new Exception(name);}static IEnumerable<Control> All(Control parent){yield return parent;foreach(Control child in parent.Controls)foreach(var c in All(child))yield return c;}static void Pump(int ms=50){var timer=System.Diagnostics.Stopwatch.StartNew();while(timer.ElapsedMilliseconds<ms){Application.DoEvents();System.Threading.Thread.Sleep(2);}}static void Save(Control c,string file){Pump();using(var image=new Bitmap(c.ClientSize.Width,c.ClientSize.Height)){using(var graphics=Graphics.FromImage(image))graphics.CopyFromScreen(c.PointToScreen(Point.Empty),Point.Empty,image.Size);image.Save(Path.GetFullPath("verify/"+file+".png"));}}
 static int WhitePixels(Control control){using(var image=new Bitmap(control.Width,control.Height)){control.DrawToBitmap(image,control.ClientRectangle);int count=0;for(int y=0;y<image.Height;y++)for(int x=0;x<image.Width;x++){var pixel=image.GetPixel(x,y);if(pixel.R>220&&pixel.G>220&&pixel.B>220)count++;}return count;}}
 [STAThread]static void Main(){Application.EnableVisualStyles();Application.SetCompatibleTextRenderingDefault(false);Exception uiError=null;Application.ThreadException+=(s,e)=>uiError=e.Exception;
  using(var v=new MainView(Path.GetFullPath("verify/layout60.json"))){var controller=new Controller(v,Path.GetFullPath("verify/backups60"),new Playback(new PlaybackTestDevice()));var project=new Project();var folder=new BoxFolder{Name="Test",Songs=Enumerable.Range(0,120).Select(i=>new Song{Artist="Artist "+i,Title="Title "+i,Album="Album",Source="missing-"+i+".mp3"}).ToList()};project.Folders.Add(folder);Call(controller,"ReplaceProject",project,null,true);Check(v.WindowState==FormWindowState.Maximized,"Start weiterhin maximiert");v.Show();v.WindowState=FormWindowState.Normal;v.ClientSize=new Size(1600,850);v.Location=Point.Empty;Pump();
   var nav=(StudioScrollPanel)Field(v,"studioNavigation");var buttons=nav.Controls.OfType<Button>().ToArray();foreach(string parent in new[]{"Cover-Studio","Audio-Werkzeuge"})buttons.Single(b=>b.Text==parent).PerformClick();Pump();
   Check(!nav.AutoScroll&&!nav.VerticalScroll.Visible&&!nav.HorizontalScroll.Visible,"Navigation verwendet keinerlei native Windows-Scrollleiste");Check(nav.ScrollRail.Visible&&nav.ScrollRail.Maximum>0,"Eigene violette Scrollleiste bei aufgeklappter Navigation sichtbar");Check(nav.ScrollRail.Width<=12&&nav.ScrollRail.ThumbBounds.Width<=6,"Schmale eigene Leiste und 5-Pixel-Regler");Check(WhitePixels(nav.ScrollRail)==0,"Kein weißer Pixel in eigener Scrollleiste");
   var library=buttons.Single(b=>b.Text=="Bibliothek");int before=library.Top;nav.ScrollRail.ScrollWheel(-120);Check(nav.ScrollOffset>0&&library.Top<before,"Mausrad verschiebt den Navigationsinhalt");int offset=nav.ScrollOffset;var message=Message.Create(buttons.Single(b=>b.Text=="MP3Gain").Handle,0x20A,new IntPtr((-120)<<16),IntPtr.Zero);Check(nav.PreFilterMessage(ref message)&&nav.ScrollOffset>offset,"Mausrad über Navigationsbutton wird korrekt weitergeleitet");
   nav.ScrollTo(0);var rail=nav.ScrollRail;var thumb=rail.ThumbBounds;Call(rail,"OnMouseDown",new MouseEventArgs(MouseButtons.Left,1,rail.Width/2,thumb.Top+thumb.Height/2,0));Call(rail,"OnMouseMove",new MouseEventArgs(MouseButtons.Left,0,rail.Width/2,rail.Height-3,0));Call(rail,"OnMouseUp",new MouseEventArgs(MouseButtons.Left,1,rail.Width/2,rail.Height-3,0));Check(nav.ScrollOffset>0,"Ziehen des Reglers verschiebt den Inhalt");
   Call(rail,"OnKeyDown",new KeyEventArgs(Keys.Home));Check(nav.ScrollOffset==0,"Home scrollt an den Anfang");Call(rail,"OnKeyDown",new KeyEventArgs(Keys.End));Check(nav.ScrollOffset==rail.Maximum,"End scrollt bis zum letzten Eintrag");int max=nav.ScrollOffset;Call(rail,"OnKeyDown",new KeyEventArgs(Keys.PageUp));Check(nav.ScrollOffset<max,"PageUp funktioniert");
   for(int i=0;i<40;i++){Call(rail,"OnMouseEnter",EventArgs.Empty);Call(rail,"OnMouseMove",new MouseEventArgs(MouseButtons.None,0,rail.Width/2,10+i,0));Call(rail,"OnMouseLeave",EventArgs.Empty);rail.Invalidate();Pump(2);}Check(WhitePixels(rail)==0,"Hover/Neuzeichnen bleiben ohne weiße Spur");nav.ScrollTo(0);
   var firstRow=v.Songs.Rows[0];var selected=v.Songs.Rows[5];v.Songs.ClearSelection();v.Songs.CurrentCell=selected.Cells[0];selected.Selected=true;v.Songs.FirstDisplayedScrollingRowIndex=4;int rowsAdded=0,rowsRemoved=0;v.Songs.RowsAdded+=(s,e)=>rowsAdded++;v.Songs.RowsRemoved+=(s,e)=>rowsRemoved++;
   bool allPlaylistsDark=true;v.ModuleHost.ControlAdded+=(s,e)=>{foreach(var list in All(e.Control).OfType<ListBox>())allPlaylistsDark&=list.BackColor==ModernTheme.Silver;};
   var watch=System.Diagnostics.Stopwatch.StartNew();for(int cycle=0;cycle<5;cycle++)foreach(string page in new[]{"MP3Gain","fre:ac","FFmpeg","Wiedergabelisten","Coversuche","Coverbearbeitung","Covergestaltung","Cover zuweisen / exportieren","Einstellungen","Bibliothek","Tag-Editor"}){Call(controller,"OpenStudioModule",page);Pump(2);Check(uiError==null,"Seitenwechsel ohne Zeichenfehler: "+page+" / "+cycle);if(page=="Einstellungen")Check(!((Control)Field(v,"studioLibrary")).Visible,"Einstellungen bleiben ohne Titelliste");if(page=="Wiedergabelisten")Check(All(v.ModuleHost).OfType<ListBox>().Single().BackColor==ModernTheme.Silver,"Wiedergabeliste dunkel");}
   Console.WriteLine("INFO 55 Seitenwechsel einschließlich Pump: "+watch.ElapsedMilliseconds+" ms");Check(allPlaylistsDark,"Wiedergabelisten bereits beim Einfügen dunkel, vor Handle-/Anzeigeaufbau");Check(rowsAdded==0&&rowsRemoved==0&&Object.ReferenceEquals(firstRow,v.Songs.Rows[0]),"Kategorienwechsel baut gemeinsame Titeltabelle nicht neu auf");Check(v.Songs.SelectedRows.Count==1&&v.Songs.SelectedRows[0]==selected,"Titelauswahl nach Kategorienwechsel erhalten");Check(((int)Field(v,"studioSwitchDepth"))==0,"Alle Seitenwechsel-Transaktionen abgeschlossen");Check(!nav.AutoScroll&&!nav.VerticalScroll.Visible,"Auch nach wiederholtem Seitenwechsel keine native Navigationsleiste");
   foreach(string page in new[]{"MP3Gain","fre:ac","FFmpeg"}){Call(controller,"OpenStudioModule",page);foreach(var number in All(v.ModuleHost).OfType<NumericUpDown>()){decimal value=number.Value;number.UpButton();number.DownButton();Check(number.Value==value,"Zahlenfeld bedienbar: "+page);number.Invalidate();number.Update();}Pump();Check(uiError==null,"Audiomodul einschließlich Zahlenfeldern fehlerfrei gezeichnet: "+page);}
   Call(controller,"OpenStudioModule","Wiedergabelisten");var playlist=All(v.ModuleHost).OfType<ListBox>().Single();All(v.ModuleHost).OfType<Button>().Single(b=>b.Text=="Auswahl hinzufügen").PerformClick();Check(playlist.Items.Count==1,"Wiedergabeliste übernimmt ausgewählten Titel nach Seitenwechsel");playlist.SelectedIndex=0;All(v.ModuleHost).OfType<Button>().Single(b=>b.Text=="Entfernen").PerformClick();Check(playlist.Items.Count==0,"Entfernen aus Wiedergabeliste weiterhin bedienbar");Save(v,"seitenwechsel60");Save(nav,"navigation60");v.ClientSize=new Size(1250,680);Pump();nav.ScrollTo(Int32.MaxValue);Check(nav.ScrollOffset==nav.ScrollRail.Maximum,"Kleine Fensterhöhe weiterhin bis zum Ende scrollbar");buttons.Single(b=>b.Text=="Cover-Studio").PerformClick();buttons.Single(b=>b.Text=="Audio-Werkzeuge").PerformClick();Check(nav.ScrollOffset<=nav.ScrollRail.Maximum,"Einklappen klemmt Scrollposition korrekt");v.ClientSize=new Size(1600,1100);Pump();Check(nav.ScrollOffset==0&&!nav.ScrollRail.Visible,"Großes Fenster braucht keine leere Scrollspur");Check(uiError==null,"Keine unbehandelte UI-Ausnahme im gesamten Ablauf");v.Close();
  }
  Console.WriteLine("BESTANDEN "+count+" Prüfungen (Mono/Xvfb; native Windows-Theme- und Redraw-API nicht ausgeführt).");
 }
}
